import { cva } from "class-variance-authority"
import type { ComponentProps } from "react"

import type { EmptySize } from "@/components/ui/empty"
import { Skeleton } from "@/components/ui/skeleton"
import { Spinner } from "@/components/ui/spinner"
import { cn } from "@/lib/utils"

const loadingStateVariants = cva("flex min-w-0 flex-col", {
  variants: {
    size: {
      inline: "gap-items",
      panel: "flex-1 gap-items p-inset-surface",
      page: "flex-1 gap-group px-inset-surface py-section",
    },
    variant: { spinner: "items-center justify-center", skeleton: "" },
  },
  compoundVariants: [{ variant: "spinner", size: "inline", className: "items-start" }],
  defaultVariants: { size: "panel", variant: "spinner" },
})

type LoadingStateProps = Omit<ComponentProps<"div">, "children"> & {
  /** What is loading, for screen readers, in the page's language. It isn't shown. */
  label: string
  variant?: "spinner" | "skeleton"
  /** How many placeholder lines the skeleton shows. */
  rows?: number
  size?: EmptySize
}

function LoadingState({
  label,
  variant = "spinner",
  rows = 3,
  size = "panel",
  className,
  ...props
}: LoadingStateProps) {
  return (
    <div
      data-slot="loading-state"
      data-variant={variant}
      data-size={size}
      aria-busy="true"
      className={cn(loadingStateVariants({ size, variant }), className)}
      {...props}
    >
      <output className="sr-only">{label}</output>
      {variant === "spinner" ? (
        <Spinner size={size === "inline" ? "md" : "lg"} className="text-muted-foreground" />
      ) : (
        Array.from({ length: rows }, (_, row) => (
          <Skeleton
            key={`row-${row}`}
            className="h-4 w-full nth-of-type-[4n+2]:w-11/12 nth-of-type-[4n+3]:w-4/5 nth-of-type-[4n]:w-2/3"
          />
        ))
      )}
    </div>
  )
}

export { LoadingState }
export type { LoadingStateProps }

"use client"

import type { ComponentProps, ReactNode } from "react"

import { Button } from "@/components/ui/button"
import { Collapsible, CollapsibleIcon, CollapsiblePanel, CollapsibleTrigger } from "@/components/ui/collapsible"
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle,
  type EmptySize,
} from "@/components/ui/empty"
import { cn } from "@/lib/utils"

type RetryProps =
  | {
      /** Runs again what failed. A returned Promise keeps the button pending until it settles. */
      onRetry: () => unknown
      retryLabel: ReactNode
    }
  | { onRetry?: undefined; retryLabel?: undefined }

type DetailsProps =
  | {
      /** Technical detail (a status code, a request id), collapsed behind `detailsLabel`. */
      details: ReactNode
      detailsLabel: ReactNode
    }
  | { details?: undefined; detailsLabel?: undefined }

type ErrorStateProps = Omit<ComponentProps<"div">, "title"> &
  RetryProps &
  DetailsProps & {
    title: ReactNode
    message?: ReactNode
    size?: EmptySize
  }

function ErrorIcon() {
  return (
    <svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
      <circle cx="12" cy="12" r="9" />
      <path d="M12 7.5v5m0 4h.01" />
    </svg>
  )
}

function ErrorState({
  title,
  message,
  onRetry,
  retryLabel,
  details,
  detailsLabel,
  size = "panel",
  className,
  ...props
}: ErrorStateProps) {
  return (
    <Empty
      size={size}
      data-tone="destructive"
      className={cn("data-[size=panel]:border-destructive/50", className)}
      {...props}
      render={<div data-slot="error-state" />}
    >
      {/* The alert holds only the title and message, so the announcement leaves out the buttons. */}
      <EmptyHeader role="alert">
        {size === "inline" ? null : (
          <EmptyMedia variant="icon" className="bg-destructive/10 text-destructive">
            <ErrorIcon />
          </EmptyMedia>
        )}
        <EmptyTitle>{title}</EmptyTitle>
        {message === undefined ? null : <EmptyDescription className="wrap-anywhere">{message}</EmptyDescription>}
      </EmptyHeader>
      {onRetry === undefined && details === undefined ? null : (
        <EmptyContent>
          {onRetry === undefined ? null : (
            <Button variant="outline" size="sm" onClick={() => onRetry()}>
              {retryLabel}
            </Button>
          )}
          {details === undefined ? null : (
            <Collapsible className="w-full items-center group-data-[size=inline]/empty:items-start">
              <CollapsibleTrigger className="min-h-control-sm text-muted-foreground">
                {detailsLabel}
                <CollapsibleIcon />
              </CollapsibleTrigger>
              <CollapsiblePanel>
                <div className="pt-items">
                  <pre className="max-w-full overflow-x-auto rounded-control bg-muted px-inset-item py-inset-item text-start font-mono text-caption whitespace-pre-wrap wrap-anywhere">
                    {details}
                  </pre>
                </div>
              </CollapsiblePanel>
            </Collapsible>
          )}
        </EmptyContent>
      )}
    </Empty>
  )
}

export { ErrorState }
export type { ErrorStateProps }

"use client"

import { useState, type ReactNode } from "react"

import { Empty, EmptyDescription, EmptyHeader, EmptyTitle, type EmptySize } from "@/components/ui/empty"
import { ErrorState } from "@/components/ui/error-state"
import { LoadingState } from "@/components/ui/loading-state"
import { Spinner } from "@/components/ui/spinner"
import { cn } from "@/lib/utils"

type DataStatus = "pending" | "error" | "success"

type DataStateLabels = {
  /** Screen-reader text while loading. */
  loading: string
  /** Screen-reader text while previous data stays on screen during a refetch. */
  refreshing: string
  errorTitle: ReactNode
  retry: ReactNode
  emptyTitle: ReactNode
  emptyDescription?: ReactNode
}

const defaultLabels = { loading: "Loading", refreshing: "Refreshing" }

type ErrorProps<E> =
  | { renderError: (error: E, retry: (() => unknown) | undefined) => ReactNode; onRetry?: () => unknown }
  | { renderError?: undefined; onRetry: () => unknown; labels: { errorTitle: ReactNode; retry: ReactNode } }
  | { renderError?: undefined; onRetry?: undefined; labels: { errorTitle: ReactNode } }

type EmptyProps = { empty: ReactNode } | { empty?: undefined; labels: { emptyTitle: ReactNode } }

type DataStateProps<T, E> = {
  status: DataStatus
  data: T | undefined
  error?: E
  /** Whether successful data counts as empty. By default an empty array, `null` or `undefined` does. */
  isEmpty?: (data: T) => boolean
  /** Replaces the default LoadingState. */
  loading?: ReactNode
  /** Keeps showing the last data while `status` is pending again, marked busy. Default true. */
  keepPreviousData?: boolean
  /** A refetch in the background while `status` stays success, as some data libraries report it. */
  fetching?: boolean
  labels?: Partial<DataStateLabels>
  size?: EmptySize
  className?: string
  children: (data: T) => ReactNode
} & ErrorProps<E> &
  EmptyProps

function defaultIsEmpty(data: unknown) {
  return Array.isArray(data) && data.length === 0
}

function messageOf(error: unknown) {
  if (error instanceof Error) return error.message
  return error === undefined || error === null ? undefined : String(error)
}

function DataState<T, E = unknown>(props: DataStateProps<T, E>) {
  const {
    status,
    data,
    error,
    isEmpty = defaultIsEmpty,
    loading,
    keepPreviousData = true,
    fetching = false,
    size = "panel",
    className,
    children,
  } = props
  const labels: Partial<DataStateLabels> & typeof defaultLabels = {
    ...defaultLabels,
    ...(props.labels as Partial<DataStateLabels> | undefined),
  }
  const [previous, setPrevious] = useState<{ data: T }>()
  if (status === "success" && data !== undefined && previous?.data !== data) setPrevious({ data })

  const blank = (value: T | undefined): value is undefined => value === undefined || value === null || isEmpty(value)
  const kept = status === "pending" && keepPreviousData ? (data ?? previous?.data) : undefined
  const shown = status === "success" ? data : kept
  const busy = (status === "pending" && !blank(shown)) || (status === "success" && fetching)

  let content: ReactNode
  if (status === "error") {
    content = props.renderError ? (
      props.renderError(error as E, props.onRetry)
    ) : props.onRetry ? (
      <ErrorState
        size={size}
        title={labels.errorTitle}
        message={messageOf(error)}
        onRetry={props.onRetry}
        retryLabel={labels.retry}
      />
    ) : (
      <ErrorState size={size} title={labels.errorTitle} message={messageOf(error)} />
    )
  } else if (status === "pending" && blank(shown)) {
    content = loading ?? <LoadingState size={size} label={labels.loading} />
  } else if (blank(shown)) {
    content = props.empty ?? (
      <Empty size={size}>
        <EmptyHeader>
          <EmptyTitle>{labels.emptyTitle}</EmptyTitle>
          {labels.emptyDescription === undefined ? null : (
            <EmptyDescription>{labels.emptyDescription}</EmptyDescription>
          )}
        </EmptyHeader>
      </Empty>
    )
  } else {
    content = children(shown)
  }

  return (
    <div
      data-slot="data-state"
      data-status={status}
      data-busy={busy ? "" : undefined}
      aria-busy={busy || undefined}
      className={cn("relative flex min-w-0 flex-col", className)}
    >
      {content}
      {busy ? (
        <span data-slot="data-state-busy" className="absolute end-0 top-0 text-muted-foreground">
          <Spinner size="sm" label={labels.refreshing} />
        </span>
      ) : null}
    </div>
  )
}

export { DataState }
export type { DataStateLabels, DataStateProps, DataStatus }
